select sua.user_id,sua.allocation_id from fnd_org_unit fou left join fnd_org_position fop on fou.UNIT_ID = fop.unit_id left join fnd_employee_assigns fea on fop.position_id = fea.POSITION_ID left join sys_user_allocation sua on sua.employee_assign_id = fea.EMPLOYEE_ASSIGN_ID left join sys_user su on su.USER_ID = sua.user_id left join fnd_employee emp on emp.EMPLOYEE_ID = fea.EMPLOYEE_ID where 1=1
